    public void Gs1DataBarExpandedStacked_MatchesReferenceRows(string text, int segments, string expected)
    {
        StackedBarcodeSymbol symbol = (StackedBarcodeSymbol)new Gs1DataBarExpandedStackedSymbology(segments).Encode(text, new BarcodeOptions());
        Assert.Equal(expected, string.Join('|', symbol.Rows.Select(Gs1DataBarStackedSymbologyTests.Modules)));
    }

    /// <summary>
    /// Section 5.5.2.3.2 of the GS1 General Specifications gives Figure 5-48, which encodes
    /// (01)90614141000015(3202)000150 in two rows of four segments, as 25.91 millimetres wide by 18.03
    /// millimetres high at an X dimension of 0.254 millimetre: 102 modules by 71, two rows of 34X and a
    /// separator of 3X.
    /// </summary>
    [Fact]
    public void Gs1DataBarExpandedStacked_MatchesTheDimensionsOfFigure548()
    {
        StackedBarcodeSymbol symbol = (StackedBarcodeSymbol)new Gs1DataBarExpandedStackedSymbology().Encode("(01)90614141000015(3202)000150", new BarcodeOptions());
        Assert.Equal(102F, symbol.WidthInModules);
        Assert.Equal(71F, symbol.HeightInModules);
        Assert.Equal([34F, 1F, 1F, 1F, 34F], symbol.Rows.Select(row => row.HeightInModules));
        Assert.Equal(0F, symbol.LeadingQuietZone);
        Assert.Equal(0F, symbol.TrailingQuietZone);
    }

    /// <summary>
    /// A bar height in millimetres sets each row.
    /// </summary>
    [Fact]
    public void Gs1DataBarExpandedStacked_BarHeightOptionSetsEachRow()
    {
        BarcodeOptions options = new() { BarHeight = 40F * DataBarExpandedEncoder.NominalXDimension };
        StackedBarcodeSymbol symbol = (StackedBarcodeSymbol)new Gs1DataBarExpandedStackedSymbology().Encode("(01)90614141000015(3202)000150", options);
        Assert.Equal(83F, symbol.HeightInModules, new ApproximateFloatComparer(1e-4F));
    }

    /// <summary>
    /// The human readable interpretation is the element strings as given, below the last row.
    /// </summary>
    [Fact]
    public void Gs1DataBarExpandedStacked_TextPrintsBelowTheLastRow()
    {
        BarcodeOptions options = new() { Font = BarcodeFonts.OcrB.CreateFont(12F) };
        StackedBarcodeSymbol symbol = (StackedBarcodeSymbol)new Gs1DataBarExpandedStackedSymbology().Encode("(01)90614141000015(3202)000150", options);
        BarcodeTextPlacement placement = Assert.Single(symbol.Text);
        Assert.Equal("(01)90614141000015(3202)000150", placement.Text);
        Assert.Equal(symbol.HeightInModules + BarcodeTextPlacement.Clearance, placement.TextEdge);
    }

    /// <summary>
    /// Section 5.5.2.3.2: "It can be printed in widths of 2 to 20 segments", and a row holds whole segment
    /// pairs.
    /// </summary>
    [Theory]
    [InlineData(0)]
    [InlineData(3)]
    [InlineData(22)]
    public void Gs1DataBarExpandedStacked_RejectsInvalidSegments(int segments)
        => Assert.ThrowsAny<ArgumentException>(() => new Gs1DataBarExpandedStackedSymbology(segments));
}
